def to_roman(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 1 or n > 3999:
        raise ValueError("n must be in range 1..3999")

    vals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    parts = []
    for value, symbol in vals:
        while n >= value:
            parts.append(symbol)
            n -= value
    return ''.join(parts)


def from_roman(s):
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if len(s) == 0:
        raise ValueError("empty string is not a valid numeral")

    roman_vals = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    # Validate characters
    for ch in s:
        if ch not in roman_vals:
            raise ValueError(f"invalid character '{ch}'")

    # Parse value
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and roman_vals[s[i]] < roman_vals[s[i + 1]]:
            # Subtract: only allow standard subtractive pairs
            allowed_pairs = {'I': ['V', 'X'], 'X': ['C', 'L'], 'C': ['D', 'M']}
            if s[i] not in allowed_pairs or s[i + 1] not in allowed_pairs[s[i]]:
                raise ValueError("invalid subtractive combination")
            total += roman_vals[s[i + 1]] - roman_vals[s[i]]
            i += 2
        else:
            total += roman_vals[s[i]]
            i += 1

    # Reconstruct and verify the string matches a canonical form
    if total < 1 or total > 3999:
        raise ValueError("value out of range")
    if to_roman(total) != s:
        raise ValueError("not a well-formed numeral")

    return total
